//! Builds a 3-slide deck of charts (PowerPoint's sample column chart, a
//! line chart with markers and data labels, a pie, a stacked bar chart on
//! edited data with blanks, a scatter chart) and writes it with
//! `fmt_pptx::write`; every chart gets an embedded workbook generated by
//! `fmt-xlsx`, so PowerPoint's "Edit Data" works.
//!
//! ```text
//! cargo run -q -p fmt-pptx --example charts_deck -- [out.pptx]
//! ```
//!
//! Default output: `testdata/pptx/out/rusuite-charts.pptx` (relative to
//! the workspace root). The deck is also built by `tests/charts.rs`.

use core_model::chart::{
    BarDirection, ChartKind, ChartTitle, DataLabels, Grouping, LabelPosition, ScatterStyle,
};
use model_show::{
    ChartData, ChartSeriesData, ChartShape, Emu, LayoutKind, Presentation, Shape, Transform,
};

/// A box in centimeters.
fn cm(x: f64, y: f64, w: f64, h: f64) -> Transform {
    Transform::new(
        Emu::from_cm(x),
        Emu::from_cm(y),
        Emu::from_cm(w),
        Emu::from_cm(h),
    )
}

fn title(p: &mut Presentation, slide: model_show::NodeId, text: &str) {
    p.add_shape(slide, Shape::text_box(cm(1.0, 0.3, 30.0, 1.5), text))
        .expect("slide exists");
}

fn chart(p: &mut Presentation, slide: model_show::NodeId, c: ChartShape, t: Transform) {
    p.add_shape(slide, Shape::chart(c, t))
        .expect("slide exists");
}

pub fn charts_deck() -> Presentation {
    let mut p = Presentation::empty(model_show::SlideSize::widescreen());

    // 1: PowerPoint's Insert › Chart sample
    let s = p.add_slide(LayoutKind::Blank);
    title(&mut p, s, "Clustered column (sample data)");
    chart(
        &mut p,
        s,
        ChartShape::sample(ChartKind::column()),
        cm(2.0, 2.5, 22.0, 14.0),
    );

    // 2: line with markers and labels, a pie
    let s = p.add_slide(LayoutKind::Blank);
    title(&mut p, s, "Line and pie");
    let mut line = ChartShape::sample(ChartKind::Line {
        grouping: Grouping::Standard,
        markers: true,
    });
    line.chart.data_labels = DataLabels {
        show_value: true,
        position: Some(LabelPosition::Top),
        ..DataLabels::default()
    };
    line.chart.title = Some(ChartTitle::literal("Revenue"));
    chart(&mut p, s, line, cm(1.0, 2.5, 16.0, 12.0));
    chart(
        &mut p,
        s,
        ChartShape::sample(ChartKind::Pie),
        cm(17.5, 2.5, 15.0, 12.0),
    );

    // 3: stacked bars on edited data (two series, five categories, a
    // blank), a scatter chart
    let s = p.add_slide(LayoutKind::Blank);
    title(&mut p, s, "Edited data and scatter");
    let mut bars = ChartShape::sample(ChartKind::Bar {
        direction: BarDirection::Bar,
        grouping: Grouping::Stacked,
    });
    bars.set_data(ChartData {
        categories: ["North", "East", "South", "West", "Ünïcødé"]
            .map(String::from)
            .to_vec(),
        series: vec![
            ChartSeriesData {
                name: "2025".into(),
                values: vec![Some(12.0), Some(7.5), None, Some(3.25), Some(9.0)],
                format_code: None,
            },
            ChartSeriesData {
                name: "2026".into(),
                values: vec![Some(14.0), Some(8.0), Some(4.0), Some(5.0), Some(11.0)],
                format_code: None,
            },
        ],
    });
    chart(&mut p, s, bars, cm(1.0, 2.5, 16.0, 12.0));
    chart(
        &mut p,
        s,
        ChartShape::sample(ChartKind::Scatter {
            style: ScatterStyle::Marker,
        }),
        cm(17.5, 2.5, 15.0, 12.0),
    );
    p
}

fn main() -> std::process::ExitCode {
    let out = std::env::args().nth(1).unwrap_or_else(|| {
        concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../testdata/pptx/out/rusuite-charts.pptx"
        )
        .to_owned()
    });
    let deck = charts_deck();
    if let Some(dir) = std::path::Path::new(&out).parent() {
        if let Err(e) = std::fs::create_dir_all(dir) {
            eprintln!("cannot create {}: {e}", dir.display());
            return std::process::ExitCode::FAILURE;
        }
    }
    match fmt_pptx::write_path(&deck, &out) {
        Ok(()) => {
            println!("wrote {out} ({} slides)", deck.slides.len());
            std::process::ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("write failed: {e}");
            std::process::ExitCode::FAILURE
        }
    }
}
